#!/bin/bash
# Uninstall script for PrusaSlicer
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling PrusaSlicer..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping PrusaSlicer if running..."
pkill -f "PrusaSlicer" 2>/dev/null || true

# Remove /Applications/Original Prusa Drivers/PrusaSlicer.app
echo "Removing /Applications/Original Prusa Drivers/PrusaSlicer.app..."
if [ -d "/Applications/Original Prusa Drivers/PrusaSlicer.app" ]; then
    rm -rf "/Applications/Original Prusa Drivers/PrusaSlicer.app" 2>/dev/null || true
elif [ -f "/Applications/Original Prusa Drivers/PrusaSlicer.app" ]; then
    rm -f "/Applications/Original Prusa Drivers/PrusaSlicer.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/PrusaSlicer
echo "Removing $HOME/Library/Application Support/PrusaSlicer..."
if [ -d "$HOME/Library/Application Support/PrusaSlicer" ]; then
    rm -rf "$HOME/Library/Application Support/PrusaSlicer" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/PrusaSlicer" ]; then
    rm -f "$HOME/Library/Application Support/PrusaSlicer" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.prusa3d.slic3r
echo "Removing $HOME/Library/Preferences/com.prusa3d.slic3r..."
if [ -d "$HOME/Library/Preferences/com.prusa3d.slic3r" ]; then
    rm -rf "$HOME/Library/Preferences/com.prusa3d.slic3r" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.prusa3d.slic3r" ]; then
    rm -f "$HOME/Library/Preferences/com.prusa3d.slic3r" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.prusa3d.slic3r.savedState
echo "Removing $HOME/Library/Saved Application State/com.prusa3d.slic3r.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.prusa3d.slic3r.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.prusa3d.slic3r.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.prusa3d.slic3r.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.prusa3d.slic3r.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
